// Where the web app and the daily job get their database address (Stage 11).
//
// 1. DATABASE_URL, when it is set (local development, tests, any host where
//    you type the address yourself). Unchanged behaviour.
// 2. Otherwise it is DERIVED: the owner address DATABASE_URL_ADMIN with the
//    user name replaced by the restricted biomedintel_app and the password
//    replaced by APP_DB_PASSWORD. On Render both come from render.yaml (the
//    owner address from the database, the password generated by Render), so
//    nobody has to edit or paste a database address by hand.
//
// Either way the app connects ONLY as biomedintel_app: a derived address can
// never use the owner, and the server and the daily job refuse to start if
// the role they connect as can bypass row-level security
// (assertRestrictedDatabaseRole). The owner address is used here only to
// learn the host, port and database name.
export const APP_ROLE = "biomedintel_app";

type Env = Record<string, string | undefined>;

export function appDatabaseUrl(env: Env = process.env): string | undefined {
  const explicit = env.DATABASE_URL?.trim();
  if (explicit) return explicit;
  const admin = env.DATABASE_URL_ADMIN?.trim();
  const password = env.APP_DB_PASSWORD ?? "";
  if (!admin || !password) return undefined;
  let url: URL;
  try {
    url = new URL(admin);
  } catch {
    return undefined;
  }
  url.username = APP_ROLE;
  url.password = password; // the URL API percent-encodes characters such as / + = @
  return url.toString();
}

/** The password inside a database address, decoded (for creating the role). */
export function passwordOf(databaseUrl: string): string {
  return decodeURIComponent(new URL(databaseUrl).password);
}
